/*!40000 ALTER TABLE `content_fields` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `content_lists`
--

DROP TABLE IF EXISTS `content_lists`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `content_lists` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `scope` varchar(120) NOT NULL,
  `key` varchar(120) NOT NULL,
  `section` varchar(120) DEFAULT NULL,
  `label` varchar(255) NOT NULL,
  `items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`items`)),
  `sort` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `content_lists_scope_key_unique` (`scope`,`key`)
