INSERT INTO `site_settings` VALUES (1,'company','company_name','Company name','text','Intelliworkz','Used in the logo alt text and the page title suffix.',1,'2026-10-12 04:39:02','2026-10-12 04:39:02'),(2,'company','copyright','Copyright line','text','Copyright © 2026 Intelliworkz Business Solutions Pvt. Ltd. All Rights Reserved.','Shown at the very bottom of every page.',2,'2026-10-12 04:39:02','2026-10-12 04:39:02'),(3,'company','footer_about','Footer description','textarea','Lorem ipsum dolor sit amet consectetur. Morbi feugiat donec felis ac aenean eget in. Facilisis sed massa eleifend aliquet aliquet leo. Commodo sit a dictum diam et nulla. Volutpat ut lectus pulvinar vel leo id at duis. Aliquet nunc dolor ultricies enim lacinia. Viverra volutpat.','The paragraph under the logo in the footer.',3,'2026-10-12 04:39:02','2026-10-12 04:39:02'),(4,'branding','logo_header','Header logo','image','assets/icons/logo.svg','Shown in the top bar and the menu panel. SVG or PNG, on a dark background.',4,'2026-10-12 04:39:02','2026-10-12 04:39:02'),(5,'branding','logo_footer','Footer logo','image','assets/icons/footer-logo.svg','Shown in the footer on a light background.',5,'2026-10-12 04:39:02','2026-10-12 04:39:02'),(6,'branding','favicon','Favicon','image','assets/images/favicon.png','Square PNG, at least 100×100 px.',6,'2026-10-12 04:39:02','2026-10-12 06:00:00'),(7,'branding','iso_image','Certification badge','image','assets/icons/iso.svg','The ISO badge in the footer.',7,'2026-10-12 04:39:02','2026-10-12 04:39:02'),(8,'contact','contact_email','Inquiry notification e-mail','email',NULL,'Optional. New inquiries are listed in the admin panel; add an address here to also receive them by e-mail.',8,'2026-10-12 04:39:02','2026-10-24 13:01:01'),(9,'contact','contact_phone','Main phone number','text',NULL,NULL,9,'2026-10-12 04:39:02','2026-10-24 13:01:01'),(10,'social','social_facebook','Facebook','url','https://www.facebook.com/intelliworkz/','Full address, e.g. https://facebook.com/yourpage',10,'2026-10-12 04:39:02','2026-10-12 06:47:38'),(11,'social','social_instagram','Instagram','url','https://www.instagram.com/intelliworkz/',NULL,11,'2026-10-12 04:39:02','2026-10-23 03:18:07'),(12,'social','social_linkedin','LinkedIn','url','https://in.linkedin.com/company/intelliworkz-business-solutions',NULL,12,'2026-10-12 04:39:02','2026-10-23 03:21:24'),(13,'seo','seo_description','Default meta description','textarea',NULL,'Used by pages that do not have their own description (about 150 characters).',13,'2026-10-12 04:39:02','2026-10-12 04:39:02'),(14,'seo','seo_image','Default share image','image','assets/images/hero-bg.png','Shown when a page is shared on social media (1200×630 px works best).',14,'2026-10-12 04:39:02','2026-10-12 04:39:02');
